def next_commands(event, order):
    if not order.get("approved", False) or order.get("status") in ("cancelled", "filled"):
        return []
    if event["kind"] == "submit" and order["status"] == "approved":
        return [{"type": "submit", "client_order_id": order["order_id"], "price": order["price"], "qty": order["qty"]}]
    if event["kind"] == "timeout":
        return [{"type": "submit", "client_order_id": order["order_id"], "price": order["price"], "qty": order["qty"]}]
    return []

